"""Genera l'informe visible sense tocar previsions ni resultats."""
import html
import json
import re


def build_research(root):
    path=root/'outputs/historical_evaluation.json'
    if not path.exists():return
    report=json.loads(path.read_text())
    esc=html.escape
    def num(v,d=3):return f'{v:.{d}f}'.replace('.',',')
    def pct(v):return num(v*100,1)+'%'
    names={'v01':'Model actual · v0.1','league':'Freqüències històriques de lliga','uniform':'Probabilitats iguals · 1/3','market_close':'Favorit de mercat · tancament (informació posterior al tall)'}
    panels=[]
    for division,competition in report['competitions'].items():
        candidate=competition['candidate_id'];names[candidate]='Candidat · força dels equips'
        rows=''.join(f'<tr><td>{esc(names[k])}</td><td>{m["hits"]}/{m["n"]}</td><td>{pct(m["accuracy"])}</td><td>{num(m["brier"])}</td><td>{num(m["logloss"])}</td></tr>' for k,m in competition['test_scores'].items())
        supported=competition['evidence_supports_candidate']
        decision=('Suport retrospectiu per a previsions noves de Primera. Motor v0.2 preparat; exigeix historial amb fonts i tall mensual verificat. Les previsions publicades conserven el model original.' if supported else 'No substituir el model actual a Segona: el candidat no millora la prova reservada. Es conserva v0.1.')
        comparisons=[]
        for reference,metrics in competition['paired_intervals_95'].items():
            for metric,v in metrics.items():comparisons.append(f'<tr><td>{esc(names[reference])}</td><td>{esc(metric)}</td><td>{num(v["delta"])}</td><td>{num(v["lower"])} a {num(v["upper"])}</td></tr>')
        config=competition['selected_config']
        valrows=''.join(f'<tr><td>{esc(k)}</td><td>{num(m["brier"])}</td><td>{num(m["logloss"])}</td></tr>' for k,m in competition['validation_scores'].items())
        calibrations=competition['test_scores'][candidate]['calibration']
        calrows=''.join(f'<tr><td>{esc(x["bin"])}</td><td>{x["n"]}</td><td>{pct(x["mean_probability"])}</td><td>{pct(x["observed"])}</td></tr>' for x in calibrations)
        panels.append(f'''<section class="panel" style="margin:22px 0"><h2>{'Primera' if division=='SP1' else 'Segona'} · prova reservada 2025/26</h2><p class="note">{decision}</p><div class="table-wrap"><table><caption>Mateixos partits per als models esportius. Menys Brier i pèrdua logarítmica és millor.</caption><thead><tr><th>Model</th><th>Encerts</th><th>Taxa</th><th>Brier</th><th>Pèrdua log.</th></tr></thead><tbody>{rows}</tbody></table></div><p class="meta">Referència addicional «sempre local»: {competition['always_home_test_hits']} encerts. Les probabilitats iguals desempaten a favor d’1 per convenció; no són una selecció aleatòria.</p><p>Paràmetres escollits només amb 2024/25: regularització {num(config['penalty'],0)}, semivida {config['half_life']} dies, correcció DC {'sí' if config['dc'] else 'no'}, temperatura {num(config['temperature'],2)}.</p><details><summary>Incertesa de la diferència amb les referències</summary><p>Remostreig aparellat de blocs de 28 dies, 2.000 repeticions i interval aproximat del 95%. Diferència candidat menys referència: valors negatius afavoreixen el candidat. És una prova exploratòria d’una temporada, no una garantia.</p><div class="table-wrap"><table><thead><tr><th>Referència</th><th>Mètrica</th><th>Diferència</th><th>Interval 95%</th></tr></thead><tbody>{''.join(comparisons)}</tbody></table></div></details><details><summary>Calibratge del signe preferit del candidat</summary><p>Compara la probabilitat estimada amb l’encert observat; cada franja pot tenir una mostra petita.</p><div class="table-wrap"><table><thead><tr><th>Franja</th><th>Partits</th><th>Probabilitat mitjana</th><th>Encert observat</th></tr></thead><tbody>{calrows}</tbody></table></div></details><details><summary>Selecció prèvia · validació 2024/25</summary><div class="table-wrap"><table><thead><tr><th>Variant</th><th>Brier</th><th>Pèrdua log.</th></tr></thead><tbody>{valrows}</tbody></table></div></details></section>''')
    sources=''.join(f'<li><a href="{esc(f["url"])}">{esc(f["division"])} · {esc(f["season"])}</a> · SHA-256: <code>{f["sha256"]}</code></li>' for f in report['source_manifest']['files'])
    style=re.search(r'<style>(.*?)</style>',(root/'work/dashboard.template.html').read_text(),re.S).group(1)
    document=f'''<!doctype html><html lang="ca"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Avaluació històrica · Quiniela</title><style>{style}</style></head><body><header><div class="brand">Q<b>.</b> Quiniela</div><span>Avaluació del model</span></header><main><div class="eyebrow">Recerca retrospectiva · 26 d’octubre de 2026</div><h1>Quins canvis milloren les previsions?</h1><p class="sub">3.368 partits de quatre temporades. Prova final reservada: 842 partits de 2025/26. Aquests resultats simulats no s’afegeixen a la taxa d’encert publicada.</p><nav class="nav"><a href="index.html#pre">Previsió</a><a href="index.html#track">Seguiment</a><a href="programacio.html">Programació</a><a href="model.html" aria-current="page">Avaluació</a></nav><section class="panel"><h2>Protocol abans de mirar la prova final</h2><p>2022/23–2023/24 aporten historial. 2024/25 serveix per escollir una de vuit variants per competició. 2025/26 avalua la variant escollida sense tornar-la a seleccionar.</p><p>{esc(report['cutoff_policy'])}</p><p>{esc(report['candidate_method'])}</p><p class="note">{esc(report['market_warning'])}</p><p class="meta">Criteri de suport: millorar Brier i pèrdua logarítmica contra v0.1 i freqüències de lliga, amb tot l’interval de diferència per sota de zero. La taxa d’encert sola no decideix el canvi.</p></section>{''.join(panels)}<section class="panel"><h2>Decisió i límits</h2><p>Primera: preparar el model v0.2 per a partits futurs amb historial verificat i conservar una comparació paral·lela amb v0.1. Segona: mantenir v0.1. Liga F: mantenir v0.1 com a experimental, sense atribuir-li la validació de Primera o Segona.</p><p>No s’han canviat les quatre columnes congelades ni s’ha optimitzat rendibilitat. Les lesions, xG i el descans continuen com a hipòtesis pendents de dades consistents.</p><ul>{''.join('<li>'+esc(x)+'</li>' for x in report['limitations'])}</ul><p><a href="historical_evaluation.json" download>Descarrega l’informe i els paràmetres</a></p><details><summary>Fonts, traçabilitat i data de descàrrega</summary><p>Recopilació secundària: <a href="https://www.football-data.co.uk/spainm.php">Football-Data.co.uk</a>. Descàrrega: {esc(report['source_manifest']['retrieved_at'])}. Les files de resultats s’han validat internament contra el signe i s’han comprovat duplicats.</p><ul>{sources}</ul><p>Referència metodològica: <a href="https://doi.org/10.1111/1467-9876.00065">Dixon i Coles</a>. La variant DC d’aquesta prova ajusta la correcció en un segon pas; no replica un ajust conjunt complet.</p></details></section><footer class="footer">Projecte experimental i informatiu. Cap garantia d’encert ni de premi. Previsions originals intactes.</footer></main></body></html>'''
    (root/'site/dist/model.html').write_text(document)
    (root/'site/dist/historical_evaluation.json').write_text(json.dumps(report,ensure_ascii=False,indent=2)+'\n')
